//! The DLL entry point. Generated by ufathom; refreshed by later dumps.
//!
//! Features of this crate change what the DLL does:
//!
//! - `proxy-version`, `proxy-dsound`, `proxy-dinput8`, `proxy-winmm`: name the
//!   built DLL after that system DLL (`version.dll`, `dsound.dll`,
//!   `dinput8.dll`, `winmm.dll`) and put it beside the game executable; the
//!   game loads it at start-up. It exports every function of the system DLL,
//!   at the same ordinals, and forwards each call to the real one
//!   (`ufathom_runtime::proxy`). Enable one of them, not several. `run` is
//!   held until the engine has started (objects loaded and, when this build
//!   has one, `GEngine` set). `build.rs` sets `cfg(ufathom_proxy)` when any of
//!   them is on.
//! - `hot-unload`: when `run` returns, the DLL unloads itself. With `inproc`,
//!   the callbacks and queued tasks this DLL registered are removed, then the
//!   `ProcessEvent` and native hooks. The DLL stays loaded if a thread is
//!   still inside them, or if another mod hooked the same slot after this
//!   one and still forwards into it (`HookError::Chained`). With `detour`,
//!   every inline detour still installed is removed too, and the DLL stays
//!   loaded if a thread is still inside a replacement or its trampoline.
//!   Without this feature the DLL stays loaded until the game exits.

use std::ffi::c_void;
use std::sync::atomic::{AtomicUsize, Ordering};

use ufathom_runtime::mem::SelfMemory;
use windows_sys::Win32::Foundation::{CloseHandle, HANDLE, HINSTANCE, HMODULE};
use windows_sys::Win32::System::Diagnostics::Debug::OutputDebugStringW;
use windows_sys::Win32::System::LibraryLoader::{
    DisableThreadLibraryCalls, GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS, GetModuleHandleExW,
};
use windows_sys::Win32::System::SystemServices::DLL_PROCESS_ATTACH;
use windows_sys::Win32::System::Threading::CreateThread;

use crate::app::run;

#[cfg(any(
    all(feature = "proxy-version", feature = "proxy-dsound"),
    all(feature = "proxy-version", feature = "proxy-dinput8"),
    all(feature = "proxy-version", feature = "proxy-winmm"),
    all(feature = "proxy-dsound", feature = "proxy-dinput8"),
    all(feature = "proxy-dsound", feature = "proxy-winmm"),
    all(feature = "proxy-dinput8", feature = "proxy-winmm"),
))]
compile_error!(
    "enable only one `proxy-*` feature: a DLL takes the exports of one system DLL"
);

static WORKER_HANDLE: AtomicUsize = AtomicUsize::new(0);

/// How long a proxy DLL waits for the engine before it gives up.
#[cfg(ufathom_proxy)]
const ENGINE_WAIT: std::time::Duration = std::time::Duration::from_secs(600);

/// How long `hot-unload` waits for threads to leave the hooks.
#[cfg(all(feature = "hot-unload", feature = "inproc"))]
const HOOK_DRAIN: std::time::Duration = std::time::Duration::from_secs(10);

/// Starts the application on a worker, outside the loader lock.
#[allow(non_snake_case)]
#[no_mangle]
pub extern "system" fn DllMain(
    module: HINSTANCE,
    reason: u32,
    _reserved: *mut c_void,
) -> i32 {
    if reason == DLL_PROCESS_ATTACH {
        // SAFETY: `module` is the handle supplied by the loader.
        unsafe { DisableThreadLibraryCalls(module) };
        // SAFETY: the entry point has the required signature and no
        // parameter is passed. The worker starts after DllMain returns.
        let handle = unsafe {
            CreateThread(
                std::ptr::null(),
                0,
                Some(worker_entry),
                std::ptr::null(),
                0,
                std::ptr::null_mut(),
            )
        };
        if handle.is_null() {
            return 0;
        }
        WORKER_HANDLE.store(handle as usize, Ordering::Release);
    }
    1
}

extern "system" fn worker_entry(_parameter: *mut c_void) -> u32 {
    let handle = WORKER_HANDLE.swap(0, Ordering::AcqRel);
    if handle != 0 {
        // SAFETY: this is the thread handle created by DllMain. Closing
        // the handle does not stop the running thread.
        unsafe { CloseHandle(handle as HANDLE) };
    }

    // Keep the module mapped while application code can run.
    let mut own_module: HMODULE = std::ptr::null_mut();
    // SAFETY: FROM_ADDRESS interprets the worker's address as a module
    // address and writes a new reference to `own_module`.
    let pinned = unsafe {
        GetModuleHandleExW(
            GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS,
            worker_entry as *const () as *const u16,
            &mut own_module,
        )
    };
    if pinned == 0 {
        debug("ufathom SDK: could not pin the application module");
        return 0;
    }

    match std::panic::catch_unwind(|| -> Result<(), Box<dyn std::error::Error>> {
        let memory = SelfMemory::new();
        #[cfg(ufathom_proxy)]
        if !wait_for_engine(&memory) {
            return Err("the engine did not start in time".into());
        }
        run(&memory)
    }) {
        Ok(Ok(())) => {}
        Ok(Err(error)) => debug(&format!("ufathom SDK: {error}")),
        Err(_) => debug("ufathom SDK: application panicked"),
    }

    #[cfg(feature = "hot-unload")]
    unload(own_module);
    0
}

/// Waits until the engine has objects and, when this build has one, a
/// `GEngine`. A proxy DLL is loaded before the game's own code runs.
#[cfg(ufathom_proxy)]
fn wait_for_engine(memory: &SelfMemory) -> bool {
    let deadline = std::time::Instant::now() + ENGINE_WAIT;
    while std::time::Instant::now() < deadline {
        if let Ok(session) = crate::session(memory) {
            let objects = session.num_objects().unwrap_or(0) > 0;
            let engine = crate::ENGINE.gengine.is_none()
                || matches!(session.gengine(), Ok(Some(_)));
            if objects && engine {
                return true;
            }
        }
        std::thread::sleep(std::time::Duration::from_millis(500));
    }
    false
}

/// Removes the hooks, then drops this thread's pin and the loader's
/// reference and exits, so the module is unmapped. Returns, leaving the
/// module loaded, when unloading would be unsafe.
#[cfg(feature = "hot-unload")]
fn unload(own_module: HMODULE) {
    use windows_sys::Win32::Foundation::FreeLibrary;
    use windows_sys::Win32::System::LibraryLoader::FreeLibraryAndExitThread;

    #[cfg(feature = "inproc")]
    if let Some(game) = ufathom_runtime::inproc::GameThread::get() {
        // Callbacks and tasks hold code of this module: drop them first.
        game.remove_owned_by_current_module();
        match game.uninstall_and_wait(HOOK_DRAIN) {
            Ok(true) => {}
            Ok(false) => {
                debug("ufathom SDK: a thread is still inside a hook; staying loaded");
                return;
            }
            // Includes a slot another mod hooked after this one: its hook
            // forwards here, so this module must stay mapped.
            Err(error) => {
                debug(&format!(
                    "ufathom SDK: cannot remove the hooks ({error}); staying loaded"
                ));
                return;
            }
        }
    }
    #[cfg(feature = "detour")]
    match ufathom_runtime::detour::uninstall_all_and_wait(HOOK_DRAIN) {
        Ok(true) => {}
        Ok(false) => {
            debug("ufathom SDK: a thread is still inside a detour; staying loaded");
            return;
        }
        Err(error) => {
            debug(&format!(
                "ufathom SDK: cannot remove the detours ({error}); staying loaded"
            ));
            return;
        }
    }
    if cfg!(ufathom_proxy) {
        // The game imports this module; it cannot be unloaded.
        return;
    }
    // SAFETY: drops the reference `GetModuleHandleExW` added above. The
    // loader's own reference keeps the module mapped.
    unsafe { FreeLibrary(own_module) };
    // SAFETY: drops the reference of the `LoadLibrary` that loaded this
    // module and ends this thread without returning into unmapped code.
    unsafe { FreeLibraryAndExitThread(own_module, 0) }
}

fn debug(message: &str) {
    let wide: Vec<u16> = message.encode_utf16().chain(Some(0)).collect();
    // SAFETY: `wide` is NUL-terminated and lives through the call.
    unsafe { OutputDebugStringW(wide.as_ptr()) };
}
